mapper.select:
SELECT S.EXCP_SCHDL_SN AS scheduleSn, S.EXCP_GROUP_SN AS groupSn, G.EXCP_GROUP_NM AS groupNm, S.EXCP_SCHDL_NM AS scheduleNm, S.BGNG_DT AS bgngDt, S.END_DT AS endDt, S.REPT_CYCLE_CN AS reptCycleCn, S.EXCP_RSN AS excpRsn, S.USE_YN AS useYn, S.NO_END_YN AS noEndYn, TIME_FORMAT(S.REPT_START_TM, '%H:%i') AS startTime, TIME_FORMAT(S.REPT_END_TM, '%H:%i') AS endTime, CASE WHEN S.REPT_CYCLE_CN LIKE 'REPEAT|%' THEN 'REPEAT' ELSE 'ONCE' END AS runType, CASE WHEN S.REPT_CYCLE_CN LIKE 'REPEAT|%' THEN SUBSTRING_INDEX(SUBSTRING_INDEX(S.REPT_CYCLE_CN,'|',2),'|',-1) ELSE NULL END AS repeatCycle, CASE WHEN S.REPT_CYCLE_CN LIKE 'REPEAT|%' THEN SUBSTRING_INDEX(S.REPT_CYCLE_CN,'|',-1) ELSE NULL END AS repeatDays, S.REG_DT AS regDt, S.MDFCN_DT AS mdfcnDt, GROUP_CONCAT(R.DSBLTY_GRD_CD ORDER BY FIELD(R.DSBLTY_GRD_CD,'EMERGENCY','HIGH','LOW','WARNING','INFO') SEPARATOR ',') AS grades FROM web_dsblty_excp_schdl_info S JOIN web_dsblty_excp_group_info G ON G.EXCP_GROUP_SN=S.EXCP_GROUP_SN LEFT JOIN web_dsblty_excp_schdl_grd_rel R ON R.EXCP_SCHDL_SN=S.EXCP_SCHDL_SN WHERE 1=1 AND S.EXCP_GROUP_SN=#{groupSn}
AND (CASE WHEN S.REPT_CYCLE_CN LIKE 'REPEAT|%' THEN 'REPEAT' ELSE 'ONCE' END)=#{runType}
AND S.USE_YN=#{useYn} AND (S.EXCP_SCHDL_NM LIKE CONCAT('%',#{keyword},'%') OR S.EXCP_RSN LIKE CONCAT('%',#{keyword},'%')) GROUP BY S.EXCP_SCHDL_SN, S.EXCP_GROUP_SN, G.EXCP_GROUP_NM, S.EXCP_SCHDL_NM, S.BGNG_DT, S.END_DT, S.REPT_CYCLE_CN, S.EXCP_RSN, S.USE_YN, S.NO_END_YN, S.REPT_START_TM, S.REPT_END_TM, S.REG_DT, S.MDFCN_DT ORDER BY S.BGNG_DT DESC, S.EXCP_SCHDL_SN DESC
